#include <bits/stdc++.h>
using namespace std;
int main(){
    int n; cin >> n;
    if (n <= 2){ cout << 1 << "\n"; return 0; }
    long long prev1 = 1, prev2 = 1, cur = 0;
    for (int i = 3; i <= n; i++){
        cur = prev1 + prev2;
        prev1 = prev2;
        prev2 = cur;
    }
    cout << cur << "\n";
}

#include <bits/stdc++.h>
using namespace std;
int main(){
    long long n; cin >> n;
    if (n <= 1){ cout << "SADƏ DEYİL\n"; return 0; }
    bool prime = true;
    for (long long i = 2; i * i <= n; i++){
        if (n % i == 0){
            prime = false;
            break;
        }
    }
    cout << (prime ? "SADƏDİR" : "SADƏ DEYİL") << "\n";
}

