#include <bits/stdc++.h>
using namespace std;
int main(){
    int n; cin >> n;
    vector<bool> isComposite(n + 1, false);
    for (int i = 2; (long long)i * i <= n; i++)
        if (!isComposite[i])
            for (int j = i * i; j <= n; j += i)
                isComposite[j] = true;
    int cnt = 0;
    for (int i = 2; i <= n; i++) if (!isComposite[i]) cnt++;
    cout << cnt << "\n";
}

